def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (ignore it)
        if '+' in v:
            v = v.split('+')[0]

        # Split core version from pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse core version
        parts = core.split('.')
        major = int(parts[0]) if len(parts) > 0 else 0
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            prerelease_identifiers = prerelease.split('.')

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_key(identifiers):
        # Version without pre-release sorts after version with pre-release
        # So we return a tuple where:
        # - If no pre-release: (1, ()) - sorts after
        # - If pre-release: (0, processed_identifiers) - sorts before
        if not identifiers:
            return (1, ())

        processed = []
        for identifier in identifiers:
            if identifier.isdigit():
                # All-digit identifiers: (0, numeric_value)
                processed.append((0, int(identifier)))
            else:
                # Other identifiers: (1, string_value)
                processed.append((1, identifier))

        return (0, tuple(processed))

    def sort_key(v):
        major, minor, patch, prerelease_identifiers = parse_version(v)
        return (major, minor, patch, prerelease_key(prerelease_identifiers))

    # Sort using stable sort to maintain input order for equal precedence
    return sorted(versions, key=sort_key)

